DO $$ BEGIN CREATE ROLE authenticated; EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE ROLE anon; EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE ROLE service_role; EXCEPTION WHEN duplicate_object THEN NULL; END $$;
CREATE TYPE lb_payment_method AS ENUM ('CASH','MOBILE_MONEY','CARD','CREDIT');
CREATE TYPE lb_mpesa_status AS ENUM ('PENDING','PAID','FAILED','CANCELLED','TIMED_OUT','NEEDS_ATTENTION');
CREATE TABLE pos_staff(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text, role text DEFAULT 'owner');
CREATE TABLE pos_audit_log(id uuid DEFAULT gen_random_uuid(), pos_tenant_id uuid, actor_type text, actor_id uuid, action text, entity_type text, entity_id uuid, metadata jsonb);
CREATE TABLE lb_businesses(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid);
CREATE TABLE lb_customers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid, name text);
CREATE TABLE lb_products(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid, name text);
CREATE TABLE lb_service_details(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid, product_id uuid UNIQUE, commission_rate numeric);
CREATE TABLE lb_sales(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid, business_id uuid, status text DEFAULT 'COMPLETED');
CREATE TABLE lb_sale_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid, sale_id uuid, product_id uuid, total_price numeric);
CREATE TABLE lb_appointments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid, status text DEFAULT 'SCHEDULED', sale_id uuid, updated_at timestamptz);
CREATE TABLE lb_folios(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid, business_id uuid, status text DEFAULT 'OPEN', settled_at timestamptz, settled_by uuid, invoice_number text, receipt_number text, updated_at timestamptz);
CREATE TABLE lb_folio_lines(id uuid DEFAULT gen_random_uuid(), folio_id uuid, amount numeric, status text DEFAULT 'POSTED');
CREATE TABLE lb_folio_payments(id uuid DEFAULT gen_random_uuid(), tenant_id uuid, business_id uuid, folio_id uuid, payment_method lb_payment_method, amount numeric, reference_no text, shift_id uuid, created_by uuid);
CREATE TABLE lb_payments(id uuid DEFAULT gen_random_uuid(), tenant_id uuid, sale_id uuid, payment_method text, reference_no text);
CREATE TABLE lb_rent_invoices(id uuid PRIMARY KEY);
CREATE TABLE lb_mpesa_transactions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, business_id uuid, shift_id uuid, customer_id uuid, phone text, amount numeric, cart_snapshot jsonb NOT NULL, checkout_request_id text UNIQUE, status lb_mpesa_status DEFAULT 'PENDING', mpesa_receipt_number text, result_code int, result_desc text, raw_callback jsonb, sale_id uuid, confirmed_at timestamptz, updated_at timestamptz, requested_by uuid, rent_invoice_id uuid REFERENCES lb_rent_invoices(id));
ALTER TABLE lb_mpesa_transactions ADD CONSTRAINT lb_mpesa_txn_has_purpose CHECK (cart_snapshot IS NOT NULL OR rent_invoice_id IS NOT NULL);
CREATE FUNCTION next_doc_number(b uuid, k text) RETURNS text LANGUAGE sql AS $$ SELECT k || '-' || floor(random()*100000)::text $$;
CREATE FUNCTION get_current_tenant_id() RETURNS uuid LANGUAGE sql AS $$ SELECT nullif(current_setting('t.tenant', true),'')::uuid $$;
CREATE FUNCTION pos28_tenant_id() RETURNS uuid LANGUAGE sql AS $$ SELECT get_current_tenant_id() $$;
CREATE FUNCTION pos28_staff_id() RETURNS uuid LANGUAGE sql AS $$ SELECT nullif(current_setting('t.staff', true),'')::uuid $$;
CREATE FUNCTION pos_has_permission(p text) RETURNS boolean LANGUAGE sql AS $$ SELECT true $$;
CREATE FUNCTION record_rent_invoice_payment(uuid,numeric,text,text,text,uuid,text,uuid) RETURNS jsonb LANGUAGE sql AS $$ SELECT '{}'::jsonb $$;
CREATE FUNCTION generate_sale_number() RETURNS text LANGUAGE sql AS $$ SELECT 'S-1' $$;
